arguments.command:
python -c "
# Test invalid brace structures in Python format strings
cases = [
    '{a',        # missing closing brace
    'a}',        # unmatched closing brace
    '{{{',       # escaped {{ + orphan {
    '}}}',       # escaped }} + orphan }
    '{a{b}',     # nested braces  
    '{}{',       # empty field + orphan {
]

for s in cases:
    try:
        result = s.format()
        print(f'{repr(s):20} -> {repr(result)}')
    except Exception as e:
        print(f'{repr(s):20} -> ERROR: {type(e).__name__}')
" 2>&1
